#include <Arduino.h>

unsigned int value = 0;
bool pending = false;
bool invalid = false;
unsigned long lastByte = 0;

void finishNumber() {
  if (pending && !invalid && value <= 31) {
    for (byte bit = 0; bit < 5; ++bit) {
      digitalWrite(2 + bit, (value & (1U << bit)) ? HIGH : LOW);
    }
  }
  value = 0;
  pending = false;
  invalid = false;
}

void setup() {
  for (byte pin = 2; pin <= 6; ++pin) {
    pinMode(pin, OUTPUT);
    digitalWrite(pin, LOW);
  }
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c >= '0' && c <= '9') {
      pending = true;
      if (value <= 31) value = value * 10 + (c - '0');
      if (value > 31) invalid = true;
    } else if (c == '\n' || c == '\r' || c == ' ' || c == '\t') {
      finishNumber();
    } else {
      invalid = true;
    }
  }
  if ((pending || invalid) && (unsigned long)(millis() - lastByte) >= 20) {
    finishNumber();
  }
}
